"""Balanced everyday recipes for the local PP filter; nutrition remains approximate."""

from .extended_recipes import ing, recipe


def pp(rid, title, description, minutes, servings, tags, method, ingredients, steps, allergens=(), difficulty="Легко"):
    result=recipe(rid,title,description,minutes,servings,["правильное питание","полезное",*tags],method,ingredients,steps,difficulty)
    result["allergens"]=list(allergens)
    return result


